def parse_positive_int(text):
    """Parse a string into a positive integer or raise ValueError."""
    num = int(text)
    if num <= 0:
        raise ValueError(f"Expected a positive integer, got {num}")
    return num

inputs = ["15", "-3", "abc", "42"]
parsed = []

for raw in inputs:
    try:
        val = parse_positive_int(raw)
    except ValueError as err:
        print(f"Skipped {raw!r}: {err}")
    else:
        parsed.append(val)

print("Valid positive integers:", parsed)

