def safe_average(nums):
    try:
        total = sum(nums)
        return total / len(nums)
    except ZeroDivisionError:
        return 0.0

print("Average of [10, 20, 30]:", safe_average([10, 20, 30]))
print("Average of []:", safe_average([]))
assert safe_average([10, 20, 30]) == 20.0
assert safe_average([]) == 0.0
